/**
 * Writes grid-exports.generated.mjs: every name `@svgrid/grid` exports, read
 * from packages/grid/src/index.ts (following `export *`).
 *
 * The codemod re-points TanStack imports at `@svgrid/grid`, and a name the grid
 * does not export (`RowSelectionState`) would leave an import that does not
 * resolve. The published CLI has no grid source to read, so the list ships as
 * a generated file. `--check` fails when it is stale; grid-exports.test.mjs runs
 * the same comparison.
 *
 *   node packages/migrate/scripts/generate-grid-exports.mjs [--check]
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { collectBarrel } from '../../mcp/scripts/api-surface.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const out = join(here, '..', 'grid-exports.generated.mjs')
const entry = join(here, '..', '..', 'grid', 'src', 'index.ts')

export function renderGridExports() {
  const { values, types } = collectBarrel(entry)
  const names = [...new Set([...values, ...types])].sort()
  return (
    '// GENERATED by scripts/generate-grid-exports.mjs from packages/grid/src/index.ts.\n' +
    '// Do not edit by hand; rerun the script after the grid changes its exports.\n' +
    'export const GRID_EXPORTS = new Set([\n' +
    names.map((n) => '  ' + JSON.stringify(n) + ',\n').join('') +
    '])\n'
  )
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const next = renderGridExports()
  if (process.argv.includes('--check')) {
    if (!existsSync(out) || readFileSync(out, 'utf8').replace(/\r\n/g, '\n') !== next) {
      console.error('migrate: grid-exports.generated.mjs is stale - run node packages/migrate/scripts/generate-grid-exports.mjs')
      process.exit(1)
    }
  } else {
    writeFileSync(out, next)
    console.log('migrate: wrote ' + out)
  }
}
